import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Custom CUDA kernel for online softmax per row ----------
softmax_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void softmax_row_kernel(const float* __restrict__ x, float* __restrict__ out, int rows, int cols) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= rows) return;

    // Shared memory for this row
    extern __shared__ float sdata[];
    // Load elements into shared memory
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        sdata[i] = x[row * cols + i];
    }

    if (blockDim.x == 1) {
        // Single thread per element: compute max and sum manually
        float max_val = -INFINITY;
        for (int j = 0; j < cols; ++j) {
            max_val = fmaxf(max_val, sdata[j]);
        }
        float sum_exp = 0.0f;
        for (int j = 0; j < cols; ++j) {
            float diff = sdata[j] - max_val;
            sum_exp += expf(diff);
        }
        out[row * cols + j] = expf(sdata[j] - max_val) / sum_exp;
    } else {
        // Reduce to find row maximum
        for (unsigned int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
            __syncthreads();
            if (threadIdx.x < blockDim.x / 2) {
                sdata[blockDim.x / 2 + threadIdx.x] = fmaxf(sdata[threadIdx.x], sdata[blockDim.x / 2 + threadIdx.x]);
            }
        }
        float row_max = sdata[0];
        __syncthreads();
        for (unsigned int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
            if (threadIdx.x < blockDim.x / 2) {
                sdata[blockDim.x / 2 + threadIdx.x] = fmaxf(sdata[threadIdx.x], row_max);
            }
        }
        float row_max = sdata[0];
        __syncthreads();

        // Compute sum of exp(x - max)
        for (int i = 0; i < cols; ++i) {
            out[row * cols + i] = expf(x[row * cols + i] - row_max) / sum_exp;
        }
    }
}

torch::Tensor softmax_cuda(torch::Tensor x) {
    auto rows = x.size(0);
    auto cols = x.size(1);
    if (rows == 0 || cols == 0) return x;

    const int block_size = 256;
    const int num_blocks_rows = (rows + block_size - 1) / block_size;
    float* out_ptr = new float[rows * cols];
    size_t shared_mem = cols * sizeof(float);
    softmax_row_kernel<<<num_blocks_rows, block_size, shared_mem>>>(x.data_ptr<float()>, out_ptr, rows, cols);
    torch::Tensor out_tensor = torch::from_blob(out_ptr, {rows, cols}).cuda().clone();
    return out_tensor;
}
"""

# Register the custom CUDA function
custom_softmax = load_inline(
    name="softmax_cuda",
    cpp_sources=softmax_kernel_source,
    cuda_sources=softmax_kernel_source,
    functions=["softmax_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.softmax_cuda = custom_softmax

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.softmax_cuda(x)
